    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address _target, uint256 _value, bytes calldata _data) public {
        _value = bound(_value, 0, 100 ether);
        vm.deal(address(c), 1000 ether);
        bool ok = true;
        try c.sendMoney(_target, _value, _data) {
            ok = true;
        } catch {
            ok = false;
        }
        (bool success,) = _target.call{value: _value}(_data);
        assertTrue(ok == success);
    }
